import { useState } from "react";

export function App() {
  const [status, setStatus] = useState("idle");
  return (
    <div>
      <button data-testid="normal-button" onClick={() => setStatus("works")}>Normal same-page button</button>
      <span data-testid="status">{status}</span>
    </div>
  );
}
